<?php
declare(strict_types=1);

function ai_max_order_lines(): int { return max(1,(int)envv('AI_MAX_ORDER_LINES','20000')); }

function ai_log_usage(?int $docId,?int $userId,?int $customerId,int $branchId,string $model,string $status,int $input=0,int $output=0,int $ms=0,?string $error=null): void
{
    $rateIn=(float)envv('AI_INPUT_COST_PER_MILLION','0.30');$rateOut=(float)envv('AI_OUTPUT_COST_PER_MILLION','2.50');
    $cost=(($input*$rateIn)+($output*$rateOut))/1000000;
    $q=db()->prepare('INSERT INTO ai_processing_logs(document_id,actor_user_id,customer_id,branch_id,model_name,status,input_tokens,output_tokens,estimated_cost_usd,processing_ms,safe_error_code) VALUES(?,?,?,?,?,?,?,?,?,?,?)');
    $q->execute([$docId,$userId,$customerId,$branchId,$model,$status,max(0,$input),max(0,$output),$cost,max(0,$ms),$error]);
}

function ai_limits(): array
{
    $pdo=db();$daily=$pdo->query("SELECT COALESCE(SUM(estimated_cost_usd),0),COALESCE(SUM(input_tokens),0),COALESCE(SUM(output_tokens),0) FROM ai_processing_logs WHERE created_at>=CURRENT_DATE()")->fetch(PDO::FETCH_NUM);
    $monthly=$pdo->query("SELECT COALESCE(SUM(estimated_cost_usd),0),COALESCE(SUM(input_tokens),0),COALESCE(SUM(output_tokens),0) FROM ai_processing_logs WHERE created_at>=DATE_FORMAT(CURRENT_DATE(),'%Y-%m-01')")->fetch(PDO::FETCH_NUM);
    $requests=$pdo->query("SELECT SUM(created_at>=CURRENT_DATE()),SUM(created_at>=DATE_FORMAT(CURRENT_DATE(),'%Y-%m-01')) FROM ai_processing_logs WHERE status IN ('success','error','limit_reached')")->fetch(PDO::FETCH_NUM);
    return ['daily_cost_usd'=>(float)$daily[0],'daily_input_tokens'=>(int)$daily[1],'daily_output_tokens'=>(int)$daily[2],'daily_requests'=>(int)($requests[0]??0),'daily_request_limit'=>(int)envv('AI_DAILY_REQUEST_LIMIT','30'),'daily_limit_usd'=>(float)envv('AI_DAILY_LIMIT_USD','2'),'monthly_cost_usd'=>(float)$monthly[0],'monthly_input_tokens'=>(int)$monthly[1],'monthly_output_tokens'=>(int)$monthly[2],'monthly_requests'=>(int)($requests[1]??0),'monthly_request_limit'=>(int)envv('AI_MONTHLY_REQUEST_LIMIT','500'),'monthly_limit_usd'=>(float)envv('AI_MONTHLY_LIMIT_USD','20')];
}

function ai_context(string $source,int $branchId): array
{
    if($source==='customer'){
        $customer=$_SESSION['customer']??null;if(!$customer)respond(['error'=>'Sign in or register before processing a document for an order.'],401);
        $q=db()->prepare('SELECT id FROM branches WHERE id=? AND active=1');$q->execute([$branchId]);if(!$q->fetchColumn())respond(['error'=>'Choose an active pickup branch.'],422);
        return ['customer'=>$customer,'actor'=>null,'branch_id'=>$branchId];
    }
    $actor=require_permission('ai.orders.access');$branchId=$branchId?:active_branch_id($actor);require_branch_access($actor,$branchId);
    $q=db()->prepare('SELECT id FROM branches WHERE id=? AND active=1');$q->execute([$branchId]);if(!$q->fetchColumn())respond(['error'=>'Choose an active branch.'],422);
    return ['customer'=>null,'actor'=>$actor,'branch_id'=>$branchId];
}

function ai_uuid(): string
{
    $bytes=random_bytes(16);$bytes[6]=chr((ord($bytes[6])&0x0f)|0x40);$bytes[8]=chr((ord($bytes[8])&0x3f)|0x80);$hex=bin2hex($bytes);return substr($hex,0,8).'-'.substr($hex,8,4).'-'.substr($hex,12,4).'-'.substr($hex,16,4).'-'.substr($hex,20);
}

function ai_save_document(PDO $pdo,array $context,string $source,array $file,string $mime,string $suffix,string $sourceFilename='',string $sourceReference='',int $pageOffset=0,?int $pageCount=null): int
{
    $root=dirname(__DIR__).'/storage/ai-documents';if(!is_dir($root)&&!mkdir($root,0700,true))throw new RuntimeException('Could not prepare private document storage.');
    $uuid=bin2hex(random_bytes(16));$stored=$uuid.'.'.$suffix;$path=$root.'/'.$stored;
    if(!move_uploaded_file($file['tmp_name'],$path)&&!copy($file['tmp_name'],$path))throw new RuntimeException('Could not store this document securely.');
    @chmod($path,0600);$hash=hash_file('sha256',$path)?:hash('sha256',$uuid);
    $q=$pdo->prepare("INSERT INTO ai_document_uploads(document_reference,source,uploaded_by,customer_id,branch_id,original_filename,source_filename,source_reference,page_offset,page_count,storage_path,mime_type,file_size,sha256,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,'uploaded')");
    $q->execute([$uuid,$source,$context['actor']['id']??null,$context['customer']['id']??null,$context['branch_id'],substr(basename((string)$file['name']),0,255),substr(basename($sourceFilename!==''?$sourceFilename:(string)$file['name']),0,255),$sourceReference?:$uuid,max(0,$pageOffset),$pageCount!==null?max(1,$pageCount):null,'ai-documents/'.$stored,$mime,(int)$file['size'],$hash]);
    return (int)$pdo->lastInsertId();
}

function ai_enqueue_job(PDO $pdo,int $documentId): array
{
    $reference=ai_uuid();$attempts=max(1,(int)envv('AI_JOB_MAX_ATTEMPTS','3'));$q=$pdo->prepare("INSERT INTO ai_processing_jobs(job_reference,document_id,status,stage,progress_percent,max_attempts) VALUES(?,?,'queued','QUEUED',0,?)");$q->execute([$reference,$documentId,$attempts]);$id=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE ai_document_uploads SET status='queued' WHERE id=?")->execute([$documentId]);$meta=$pdo->prepare('SELECT mime_type,page_offset,page_count FROM ai_document_uploads WHERE id=?');$meta->execute([$documentId]);$document=$meta->fetch();$isPdf=strtolower((string)($document['mime_type']??''))==='application/pdf';$pdo->prepare("INSERT INTO ai_processing_batches(job_id,batch_index,page_start,page_end,status) VALUES(?,0,?,?, 'queued')")->execute([$id,$isPdf?(int)$document['page_offset']+1:null,$isPdf&&$document['page_count']!==null?(int)$document['page_offset']+(int)$document['page_count']:null]);return ['id'=>$id,'reference'=>$reference];
}

function ai_job_status(PDO $pdo,int $jobId,bool $withResult=false): ?array
{
    $q=$pdo->prepare('SELECT j.id,j.job_reference,j.document_id,j.status,j.stage,j.progress_percent,j.attempt_count,j.max_attempts,j.error_message,j.result_json,j.processing_ms,j.locked_until,j.created_at,j.started_at,j.completed_at,d.original_filename,d.source_filename,d.source_reference,d.page_offset,d.page_count,d.mime_type,d.file_size,d.sha256 FROM ai_processing_jobs j JOIN ai_document_uploads d ON d.id=j.document_id WHERE j.id=?');$q->execute([$jobId]);$job=$q->fetch();if(!$job)return null;$canDelete=in_array(strtolower((string)$job['status']),['queued','retry_pending','failed'],true)||(strtolower((string)$job['status'])==='processing'&&($job['locked_until']===null||strtotime((string)$job['locked_until'])<=time()));$out=['id'=>(int)$job['id'],'job_id'=>(int)$job['id'],'job_reference'=>$job['job_reference'],'document_id'=>(int)$job['document_id'],'filename'=>$job['source_filename']?:$job['original_filename'],'chunk_filename'=>$job['original_filename'],'source_reference'=>$job['source_reference'],'page_offset'=>(int)$job['page_offset'],'page_count'=>$job['page_count']===null?null:(int)$job['page_count'],'mime_type'=>$job['mime_type'],'file_size'=>(int)$job['file_size'],'sha256'=>$job['sha256'],'status'=>strtoupper($job['status']),'stage'=>$job['stage'],'progress_percent'=>(int)$job['progress_percent'],'attempt_count'=>(int)$job['attempt_count'],'max_attempts'=>(int)$job['max_attempts'],'can_delete'=>$canDelete,'error'=>$job['error_message'],'processing_ms'=>$job['processing_ms']===null?null:(int)$job['processing_ms'],'created_at'=>$job['created_at'],'started_at'=>$job['started_at'],'completed_at'=>$job['completed_at']];if($withResult&&$job['result_json'])$out['result']=json_decode((string)$job['result_json'],true);return $out;
}

function ai_process_job(PDO $pdo,int $jobId): array
{
    @ini_set('max_execution_time','300');@set_time_limit(300);@ignore_user_abort(true);$lockSeconds=max(60,(int)envv('AI_JOB_LOCK_SECONDS','900'));$claim=$pdo->prepare("UPDATE ai_processing_jobs SET status='processing',stage='VALIDATING',progress_percent=5,attempt_count=attempt_count+1,started_at=COALESCE(started_at,NOW()),locked_until=DATE_ADD(NOW(),INTERVAL ? SECOND),error_message=NULL WHERE id=? AND (status='queued' OR (status='retry_pending' AND (locked_until IS NULL OR locked_until<NOW())) OR (status='processing' AND locked_until<NOW()))");$claim->execute([$lockSeconds,$jobId]);if(!$claim->rowCount())return ai_job_status($pdo,$jobId,true)??['status'=>'NOT_FOUND'];
    $pdo->prepare("UPDATE ai_processing_batches SET status='processing',started_at=COALESCE(started_at,NOW()),error_message=NULL WHERE job_id=? AND batch_index=0")->execute([$jobId]);$q=$pdo->prepare('SELECT j.document_id,j.attempt_count,j.max_attempts,d.branch_id,d.source,d.customer_id,d.uploaded_by,d.original_filename,d.source_filename,d.source_reference,d.page_offset,d.page_count,d.storage_path,d.mime_type FROM ai_processing_jobs j JOIN ai_document_uploads d ON d.id=j.document_id WHERE j.id=?');$q->execute([$jobId]);$job=$q->fetch();if(!$job)return ['status'=>'NOT_FOUND'];$docId=(int)$job['document_id'];$started=microtime(true);$source=$job['source'];$isCustomer=$source==='customer';
    try{
        $pdo->prepare("UPDATE ai_document_uploads SET status='processing' WHERE id=?")->execute([$docId]);$storageRoot=realpath(dirname(__DIR__).'/storage/ai-documents');$filePath=$storageRoot?realpath($storageRoot.'/'.basename((string)$job['storage_path'])):false;if(!$storageRoot||!$filePath||!str_starts_with($filePath,$storageRoot.DIRECTORY_SEPARATOR)||!is_file($filePath))throw new RuntimeException('The stored document could not be found. Upload the document again.');
        $spreadsheet=in_array(strtolower(pathinfo((string)$job['original_filename'],PATHINFO_EXTENSION)),['xls','xlsx','csv'],true);$model=envv('GEMINI_MODEL','gemini-3.5-flash-lite');
        if($spreadsheet){$pdo->prepare("UPDATE ai_processing_jobs SET stage='EXTRACTING',progress_percent=20 WHERE id=?")->execute([$jobId]);$items=ai_parse_spreadsheet($filePath,(string)$job['original_filename']);$result=['items'=>$items,'_meta'=>['model'=>'phpspreadsheet','input_tokens'=>0,'output_tokens'=>0]];}else{$pdo->prepare("UPDATE ai_processing_jobs SET stage='EXTRACTING',progress_percent=20 WHERE id=?")->execute([$jobId]);$result=ai_gemini_extract($filePath,(string)$job['mime_type'],(string)($job['source_filename']?:$job['original_filename']));}
        $offset=(int)$job['page_offset'];if($offset>0)foreach($result['items'] as &$item)if(isset($item['page_number']))$item['page_number']=(int)$item['page_number']+$offset;unset($item);
        $pdo->prepare("UPDATE ai_processing_jobs SET stage='MATCHING_INVENTORY',progress_percent=72 WHERE id=?")->execute([$jobId]);$items=ai_persist_extraction($pdo,$docId,$result,(int)$job['branch_id'],$isCustomer);$meta=$result['_meta']??[];ai_log_usage($docId,$job['uploaded_by']?(int)$job['uploaded_by']:null,$job['customer_id']?(int)$job['customer_id']:null,(int)$job['branch_id'],$meta['model']??$model,'success',(int)($meta['input_tokens']??0),(int)($meta['output_tokens']??0),(int)($meta['processing_ms']??((microtime(true)-$started)*1000)));
        $warningCount=count(array_filter($items,static fn($row)=>!empty($row['uncertain_fields'])||in_array($row['status'],['NEEDS_VERIFICATION','AMBIGUOUS_MATCH','NOT_FOUND','CROSSED_OUT'],true)));$finalStatus=$warningCount?'completed_with_warnings':'completed';$resultPayload=['document_id'=>$docId,'filename'=>$job['source_filename']?:$job['original_filename'],'source_reference'=>$job['source_reference'],'page_offset_applied'=>true,'items'=>$items,'document_date'=>$result['document_date']??null,'heading'=>$result['heading']??null];$elapsed=(int)((microtime(true)-$started)*1000);$json=json_encode($resultPayload,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);$save=$pdo->prepare('UPDATE ai_processing_jobs SET status=?,stage=?,progress_percent=100,result_json=?,processing_ms=?,completed_at=NOW(),locked_until=NULL WHERE id=?');$save->execute([$finalStatus,'COMPLETED',$json,$elapsed,$jobId]);$pdo->prepare("UPDATE ai_processing_batches SET status='completed',result_json=?,processing_ms=?,completed_at=NOW() WHERE job_id=? AND batch_index=0")->execute([$json,$elapsed,$jobId]);audit('ai.document.process','ai_document',$docId,['branch_id'=>(int)$job['branch_id'],'source'=>$source,'items'=>count($items),'status'=>$finalStatus]);return ai_job_status($pdo,$jobId,true)??['status'=>'NOT_FOUND'];
    }catch(Throwable $e){$message=$e->getMessage();$lower=strtolower($message);$retryable=str_contains($lower,'quota')||str_contains($lower,'rate limit')||str_contains($lower,'temporarily')||str_contains($lower,'could not be reached')||str_contains($lower,'timeout');$canRetry=$retryable&&(int)$job['attempt_count']<(int)$job['max_attempts'];$status=$canRetry?'retry_pending':'failed';$httpStatus=$message==='AI is not configured yet. Add GEMINI_API_KEY to the server .env. Excel upload and manual entry are still available.'?503:(str_contains($lower,'quota')||str_contains($lower,'rate limit')?429:(str_contains($lower,'busy')||str_contains($lower,'temporarily')?503:(str_contains($lower,'could not be reached')?504:422)));$pdo->prepare('UPDATE ai_processing_jobs SET status=?,stage=?,progress_percent=0,error_message=?,locked_until=NULL WHERE id=?')->execute([$status,strtoupper($status),substr($message,0,2000),$jobId]);$pdo->prepare("UPDATE ai_processing_batches SET status='failed',error_message=?,completed_at=NOW() WHERE job_id=? AND batch_index=0")->execute([substr($message,0,2000),$jobId]);$pdo->prepare("UPDATE ai_document_uploads SET status='failed' WHERE id=?")->execute([$docId]);try{ai_log_usage($docId,$job['uploaded_by']?(int)$job['uploaded_by']:null,$job['customer_id']?(int)$job['customer_id']:null,(int)$job['branch_id'],envv('GEMINI_MODEL','gemini-3.5-flash-lite'),'error',0,0,(int)((microtime(true)-$started)*1000),$canRetry?'retry_pending':'processing_failed');}catch(Throwable){}return ai_job_status($pdo,$jobId,true)??['status'=>'NOT_FOUND','http_status'=>$httpStatus];}
}

function ai_authorize_job(PDO $pdo,int $jobId,bool $isCustomer): array
{
    $actor=null;$customer=null;if($isCustomer){$customer=$_SESSION['customer']??null;if(!$customer)respond(['error'=>'Sign in before viewing this document job.'],401);}else{$actor=require_permission('ai.orders.access');}
    $q=$pdo->prepare('SELECT j.id,d.branch_id,d.source,d.customer_id,d.uploaded_by FROM ai_processing_jobs j JOIN ai_document_uploads d ON d.id=j.document_id WHERE j.id=?');$q->execute([$jobId]);$row=$q->fetch();if(!$row||$row['source']!==($isCustomer?'customer':'pos'))respond(['error'=>'Document job not found.'],404);
    if($isCustomer){if((int)$row['customer_id']!==(int)$customer['id'])respond(['error'=>'Document job not found.'],404);}else{if((int)$row['uploaded_by']!==(int)$actor['id']&&$actor['role']!=='Administrator')respond(['error'=>'Document job not found.'],404);require_branch_access($actor,(int)$row['branch_id']);}
    return ['actor'=>$actor,'customer'=>$customer,'branch_id'=>(int)$row['branch_id']];
}

function ai_persist_extraction(PDO $pdo,int $documentId,array $result,int $branchId,bool $publicOnly): array
{
    $startedTransaction=!$pdo->inTransaction();if($startedTransaction)$pdo->beginTransaction();
    try{
    // A retry can happen after extraction rows were committed but a later
    // logging/audit step failed. Replace that document's prior extraction
    // inside this transaction so retries remain idempotent.
    $pdo->prepare('DELETE FROM ai_extracted_products WHERE document_id=?')->execute([$documentId]);
    $items=ai_match_products($pdo,$result['items']??[],$branchId,$publicOnly);$insert=$pdo->prepare('INSERT INTO ai_extracted_products(document_id,original_text,original_product_name,normalized_product_name,generic_name,brand_name,strength,dosage_form,packaging,requested_quantity,original_unit,interpreted_unit,unit_source,units_per_box,unit_price,total_price,category_name,page_number,column_number,line_number,extraction_confidence,uncertain_fields,is_crossed_out,is_duplicate,match_status,matched_product_id,match_confidence,verification_notes,reviewed_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
    $match=$pdo->prepare('INSERT IGNORE INTO ai_product_matches(extracted_product_id,product_id,status,confidence,verification_notes) VALUES(?,?,?,?,?)');
    foreach($items as $item){$best=$item['matched_product']??null;$insert->execute([$documentId,$item['original_text'],$item['product_name']?:null,$item['normalized_product_name']?:null,$item['generic_name'],$item['brand_name'],$item['strength'],$item['dosage_form'],$item['packaging'],$item['requested_quantity'],$item['original_unit'],$item['interpreted_unit'],$item['unit_source'],$item['units_per_box'],$item['unit_price'],$item['total_price'],$item['category'],$item['page_number'],$item['column_number'],$item['line_number'],$item['extraction_confidence'],json_encode($item['uncertain_fields']),$item['is_crossed_out']?1:0,$item['is_duplicate']?1:0,$item['status'],$best['product_id']??null,$best['confidence']??null,null,json_encode(['candidates'=>$item['candidates'],'raw'=>$item],JSON_UNESCAPED_UNICODE)]);$eid=(int)$pdo->lastInsertId();$item['extracted_id']=$eid;foreach($item['candidates'] as $candidate)$match->execute([$eid,$candidate['product_id'],$candidate['confidence']>=.95?'EXACT_MATCH':($candidate['confidence']>=.75?'SUGGESTED_MATCH':'NEEDS_VERIFICATION'),$candidate['confidence'],$candidate['confidence']<.95?'Human verification required':null]);}
    $pdo->prepare("UPDATE ai_document_uploads SET status='processed',extraction_json=? WHERE id=?")->execute([json_encode(['document_date'=>$result['document_date']??null,'heading'=>$result['heading']??null],JSON_UNESCAPED_UNICODE),$documentId]);
    if($startedTransaction)$pdo->commit();return $items;
    }catch(Throwable $e){if($startedTransaction&&$pdo->inTransaction())$pdo->rollBack();throw $e;}
}

function ai_handle_api(string $path,string $method): bool
{
    if(($path==='/ai/scan'||$path==='/ai/import'||$path==='/customer/ai/scan'||$path==='/customer/ai/import')&&$method==='POST'){@ini_set('max_execution_time','300');@set_time_limit(300);}
    if($path==='/ai/categories'&&$method==='GET'){$actor=require_permission('products.create');respond(['categories'=>db()->query('SELECT id,name FROM product_categories ORDER BY name')->fetchAll()]);}
    if($path==='/ai/categories'&&$method==='POST'){$actor=require_permission('products.create');csrf_check();$name=body_string(json_input(),'name',120,true);$q=db()->prepare('SELECT id FROM product_categories WHERE LOWER(name)=LOWER(?) LIMIT 1');$q->execute([$name]);if($q->fetchColumn())respond(['error'=>'That category already exists.'],409);try{$q=db()->prepare('INSERT INTO product_categories(name) VALUES(?)');$q->execute([$name]);$id=(int)db()->lastInsertId();audit('product.category.create','product_category',$id,['name'=>$name]);respond(['category'=>['id'=>$id,'name'=>$name]],201);}catch(Throwable){respond(['error'=>'Unable to create this category.'],422);}}
    if(($path==='/ai/catalog'||$path==='/customer/ai/catalog')&&$method==='GET'){
        $isCustomer=str_starts_with($path,'/customer/');$branchId=(int)($_GET['branch_id']??0);
        if($isCustomer){$customer=$_SESSION['customer']??null;if(!$customer)respond(['error'=>'Sign in or register to select inventory products for an order.'],401);$q=db()->prepare('SELECT id FROM branches WHERE id=? AND active=1');$q->execute([$branchId]);if(!$q->fetchColumn())respond(['error'=>'Choose an active pickup branch.'],422);}
        else{$actor=require_permission('ai.orders.access');$branchId=$branchId?:active_branch_id($actor);require_branch_access($actor,$branchId);}
        $sql='SELECT p.id,p.code,p.name,p.units_per_box,p.allow_individual,COALESCE(bi.stock_units,0) stock_units,COALESCE(FLOOR(bi.stock_units/p.units_per_box),0) available_boxes,COALESCE(bi.box_price,p.box_price) box_price,c.name category FROM products p LEFT JOIN branch_inventory bi ON bi.product_id=p.id AND bi.branch_id=? LEFT JOIN product_categories c ON c.id=p.category_id WHERE p.is_active=1'.($isCustomer?' AND p.is_public=1':'').' ORDER BY p.name LIMIT 3000';$q=db()->prepare($sql);$q->execute([$branchId]);$categories=$isCustomer?[]:db()->query('SELECT id,name FROM product_categories ORDER BY name')->fetchAll();respond(['products'=>$q->fetchAll(),'categories'=>$categories,'branch_id'=>$branchId]);
    }
    if(($path==='/ai/usage'||$path==='/ai/status')&&$method==='GET'){
        require_permission('ai.orders.access');$limits=ai_limits();$q=db()->query("SELECT status,COUNT(*) requests FROM ai_processing_logs WHERE created_at>=CURRENT_DATE() GROUP BY status");
        respond(['configured'=>envv('GEMINI_API_KEY',envv('GOOGLE_GEMINI_API_KEY'))!=='','model'=>envv('GEMINI_MODEL','gemini-3.5-flash-lite'),'usage'=>$limits,'requests_today'=>$q->fetchAll()]);
    }
    $isCustomer=str_starts_with($path,'/customer/ai/');$base=$isCustomer?'/customer/ai/':'/ai/';
    $jobRoute='#^'.preg_quote($base,'#').'jobs(?:/(\d+)(?:/(run|retry))?)?$#';if(preg_match($jobRoute,$path,$jobMatch)){
        if($method==='GET'&&empty($jobMatch[1])){if($isCustomer){$customer=$_SESSION['customer']??null;if(!$customer)respond(['error'=>'Sign in to view your document processing status.'],401);$q=db()->prepare('SELECT j.id FROM ai_processing_jobs j JOIN ai_document_uploads d ON d.id=j.document_id WHERE d.source=\'customer\' AND d.customer_id=? ORDER BY j.created_at DESC LIMIT 100');$q->execute([$customer['id']]);}else{$actor=require_permission('ai.orders.access');$branchId=(int)($_GET['branch_id']??active_branch_id($actor));require_branch_access($actor,$branchId);$sql='SELECT j.id FROM ai_processing_jobs j JOIN ai_document_uploads d ON d.id=j.document_id WHERE d.source=\'pos\' AND d.branch_id=?'.($actor['role']==='Administrator'?'':' AND d.uploaded_by=?').' ORDER BY j.created_at DESC LIMIT 100';$q=db()->prepare($sql);$actor['role']==='Administrator'?$q->execute([$branchId]):$q->execute([$branchId,$actor['id']]);}$jobs=[];foreach($q->fetchAll(PDO::FETCH_COLUMN) as $id)$jobs[]=ai_job_status(db(),(int)$id);respond(['jobs'=>$jobs]);}
        if(empty($jobMatch[1]))respond(['error'=>'Document job ID is required.'],404);$jobId=(int)$jobMatch[1];ai_authorize_job(db(),$jobId,$isCustomer);
        if($method==='GET'&&empty($jobMatch[2])){$job=ai_job_status(db(),$jobId,true);respond(['job'=>$job],$job?200:404);}
        if($method==='POST'&&($jobMatch[2]??'')==='run'){csrf_check();session_write_close();$job=ai_process_job(db(),$jobId);respond(['job'=>$job]);}
        if($method==='POST'&&($jobMatch[2]??'')==='retry'){csrf_check();$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare("UPDATE ai_processing_jobs SET status='queued',stage='QUEUED',progress_percent=0,attempt_count=0,error_message=NULL,result_json=NULL,processing_ms=NULL,started_at=NULL,completed_at=NULL,locked_until=NULL WHERE id=? AND status IN('failed','retry_pending')");$q->execute([$jobId]);if($q->rowCount())$pdo->prepare("UPDATE ai_document_uploads SET status='queued' WHERE id=(SELECT document_id FROM ai_processing_jobs WHERE id=?)")->execute([$jobId]);$pdo->commit();respond(['job'=>ai_job_status($pdo,$jobId,true),'queued'=>(bool)$q->rowCount()]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();respond(['error'=>'Unable to queue this document for retry.'],500);}}
        if($method==='DELETE'&&empty($jobMatch[2])){
            csrf_check();$pdo=db();$pdo->beginTransaction();$storagePath='';$documentId=0;$oldStatus='';
            try{
                $q=$pdo->prepare('SELECT j.status,j.locked_until,d.id document_id,d.status document_status,d.storage_path FROM ai_processing_jobs j JOIN ai_document_uploads d ON d.id=j.document_id WHERE j.id=? FOR UPDATE');$q->execute([$jobId]);$row=$q->fetch();
